mapper.delete:
DELETE FROM `stat_daily`
WHERE stat_date = #{statDate}
  AND caliber_version = #{caliberVersion}

mapper.select:
SELECT s.stat_date AS statDate,
       s.metric    AS metric,
       SUM(s.value) AS total
FROM `stat_daily` s
WHERE s.metric IN

    #{metric}

  AND s.caliber_version = #{caliberVersion}
  AND s.stat_date >= #{from}
  AND s.stat_date <= #{to}
GROUP BY s.stat_date, s.metric

SELECT DISTINCT s.stat_date
FROM `stat_daily` s
WHERE s.metric = #{metric}
  AND s.caliber_version = #{caliberVersion}
  AND s.stat_date >= #{from}
  AND s.stat_date <= #{to}
ORDER BY s.stat_date
